//! Generates `../src/casefold_table.rs` from `unicase`'s full case folding.
//!
//! QuickGlass patch tool. pulldown-cmark compares link labels with `unicase`,
//! whose folding table costs ~33 KB in the binary. This dumps unicase's exact
//! fold for every char and re-encodes it as runs, so the replacement in
//! `src/casefold.rs` folds identically at a fraction of the size.
//!
//! Run from vendor/pulldown-cmark:  cargo run --release --manifest-path casefold-gen/Cargo.toml

use std::fmt::Write;

/// A run of single-char folds: `start, start+stride, ...` (len of them) each
/// map to `cp + delta`.
struct Run {
    start: u32,
    len: u32,
    stride: u32,
    delta: i32,
}

fn main() {
    let mut singles: Vec<(u32, u32)> = Vec::new();
    let mut multis: Vec<(u32, Vec<u32>)> = Vec::new();
    for cp in 0..=0x10FFFFu32 {
        let Some(c) = char::from_u32(cp) else { continue };
        let s = c.to_string();
        let folded: Vec<u32> =
            unicase::UniCase::unicode(s.as_str()).to_folded_case().chars().map(|f| f as u32).collect();
        match folded.as_slice() {
            [one] if *one == cp => {}
            [one] => singles.push((cp, *one)),
            _ => multis.push((cp, folded)),
        }
    }

    // Greedy run building over the sorted singles. A run extends while the next
    // mapping keeps the same delta and the same stride (1 or 2).
    let mut runs: Vec<Run> = Vec::new();
    let mut i = 0;
    while i < singles.len() {
        let (start, to) = singles[i];
        let delta = to as i32 - start as i32;
        let mut best = Run { start, len: 1, stride: 1, delta };
        for stride in [1u32, 2] {
            let mut len = 1;
            while i + len < singles.len() {
                let (cp, to) = singles[i + len];
                if cp != start + stride * len as u32 || to as i32 - cp as i32 != delta {
                    break;
                }
                len += 1;
            }
            if len as u32 > best.len {
                best = Run { start, len: len as u32, stride, delta };
            }
        }
        i += best.len as usize;
        runs.push(best);
    }
    assert!(runs.iter().all(|r| r.len < 0x8000), "run length exceeds 15 bits");

    let mut out = String::new();
    out.push_str("// Generated by casefold-gen from unicase 2.9.0. Do not edit.\n");
    out.push_str("// QuickGlass patch: see src/casefold.rs.\n\n");
    writeln!(out, "/// First code point of each run, ascending.\npub(crate) const RUN_START: [u32; {}] = [", runs.len()).unwrap();
    for chunk in runs.chunks(12) {
        let items: Vec<String> = chunk.iter().map(|r| format!("0x{:X}", r.start)).collect();
        writeln!(out, "    {},", items.join(", ")).unwrap();
    }
    out.push_str("];\n\n");
    writeln!(out, "/// `len << 1 | (stride - 1)` for each run.\npub(crate) const RUN_LEN_STRIDE: [u16; {}] = [", runs.len()).unwrap();
    for chunk in runs.chunks(16) {
        let items: Vec<String> = chunk.iter().map(|r| format!("{}", r.len << 1 | (r.stride - 1))).collect();
        writeln!(out, "    {},", items.join(", ")).unwrap();
    }
    out.push_str("];\n\n");
    writeln!(out, "/// Amount added to a code point in the run to fold it.\npub(crate) const RUN_DELTA: [i32; {}] = [", runs.len()).unwrap();
    for chunk in runs.chunks(16) {
        let items: Vec<String> = chunk.iter().map(|r| format!("{}", r.delta)).collect();
        writeln!(out, "    {},", items.join(", ")).unwrap();
    }
    out.push_str("];\n\n");

    let mut chars: Vec<u32> = Vec::new();
    let mut ends: Vec<usize> = Vec::new();
    for (_, folded) in &multis {
        chars.extend(folded);
        ends.push(chars.len());
    }
    writeln!(out, "/// Code points that fold to more than one char, ascending.\npub(crate) const MULTI_KEY: [u32; {}] = [", multis.len()).unwrap();
    for chunk in multis.chunks(12) {
        let items: Vec<String> = chunk.iter().map(|(cp, _)| format!("0x{cp:X}")).collect();
        writeln!(out, "    {},", items.join(", ")).unwrap();
    }
    out.push_str("];\n\n");
    writeln!(out, "/// End offset of each MULTI_KEY's expansion in MULTI_CHARS.\npub(crate) const MULTI_END: [u16; {}] = [", ends.len()).unwrap();
    for chunk in ends.chunks(16) {
        let items: Vec<String> = chunk.iter().map(|e| e.to_string()).collect();
        writeln!(out, "    {},", items.join(", ")).unwrap();
    }
    out.push_str("];\n\n");
    writeln!(out, "/// Concatenated multi-char expansions.\npub(crate) const MULTI_CHARS: [char; {}] = [", chars.len()).unwrap();
    for chunk in chars.chunks(10) {
        let items: Vec<String> = chunk.iter().map(|c| format!("'\\u{{{c:X}}}'")).collect();
        writeln!(out, "    {},", items.join(", ")).unwrap();
    }
    out.push_str("];\n");

    std::fs::write("src/casefold_table.rs", out).expect("run from vendor/pulldown-cmark");
    eprintln!(
        "singles={} runs={} multis={} multi_chars={} (~{} bytes of tables)",
        singles.len(),
        runs.len(),
        multis.len(),
        chars.len(),
        runs.len() * 10 + multis.len() * 6 + chars.len() * 4
    );
}
